(()=>{const A='#e6b1c0',reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#fff1;z-index:100}.fxbar i{display:block;height:100%;width:0;background:${A};box-shadow:0 0 18px ${A}}.fxo{position:fixed;z-index:-1;pointer-events:none;border-radius:50%;filter:blur(85px);opacity:.12}.fxo.a{width:360px;height:360px;left:-130px;top:18%;background:${A};animation:drift 15s ease-in-out infinite}.fxo.b{width:340px;height:340px;right:-150px;bottom:8%;background:#6b4650;animation:drift 18s ease-in-out infinite reverse}.fxr{opacity:0;transform:translateY(40px) scale(.985);transition:1.1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.fx-spark,.fx-particle{position:fixed;pointer-events:none;z-index:4;color:${A};opacity:0}.fx-spark{animation:spark 5s ease-out infinite}.fx-particle{width:2px;height:2px;border-radius:50%;background:${A};box-shadow:0 0 8px ${A};animation:particle 7s ease-in-out infinite}.proposal-accepted:after{content:'♡';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font-size:min(35vw,240px);color:${A};text-shadow:0 0 50px #fff;animation:accept .9s ease both}@keyframes spark{0%{transform:translateY(20vh) scale(.5) rotate(0);opacity:0}18%{opacity:.8}100%{transform:translateY(-80vh) scale(1.4) rotate(240deg);opacity:0}}@keyframes particle{0%{transform:translate3d(0,15vh,0) scale(.5);opacity:0}20%{opacity:.45}50%{transform:translate3d(25px,-25vh,0) scale(1)}100%{transform:translate3d(-20px,-70vh,0) scale(.2);opacity:0}}@keyframes drift{50%{transform:translate(80px,-45px)}}@keyframes accept{0%{opacity:0;transform:scale(.5)}45%{opacity:1;transform:scale(1.12)}100%{opacity:0;transform:scale(1.4)} }@media(max-width:700px){.fx-cursor{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);['a','b'].forEach(x=>{const o=document.createElement('div');o.className='fxo '+x;b.appendChild(o)});if(!reduce){for(let i=0;i<20;i++){const x=document.createElement('span');x.className='fx-spark';x.textContent=['✦','✧','♡'][i%3];x.style.left=Math.random()*100+'%';x.style.fontSize=8+Math.random()*16+'px';x.style.animationDelay=-Math.random()*5+'s';b.appendChild(x)}for(let i=0;i<32;i++){const x=document.createElement('i');x.className='fx-particle';x.style.left=Math.random()*100+'%';x.style.bottom=-5-Math.random()*20+'px';x.style.animationDelay=-Math.random()*7+'s';x.style.animationDuration=5+Math.random()*5+'s';b.appendChild(x)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();